local T = import("test/environment.lua")
local lzma = import("goluwa/codecs/lzma.lua")
local ffi = require("ffi")
local vectors = {
	{
		name = "text",
		raw = "",
		compressed = "",
	},
	{
		name = "repeat",
		raw = "",
		compressed = "5d00000100080700000000000000309888ad4b3712a33185ddfa5304dfbdf619fffffa508000",
	},
	{
		name = "random",
		raw = "",
		compressed = "",
	},
	{
		name = "mixed_lc0_lp2_pb0",
		raw = "",
		compressed = "",
	},
	{
		name = "source_lump",
		raw = "",
		compressed = "",
	},
}

local function from_hex(hex)
	return (hex:gsub("%x%x", function(byte)
		return string.char(tonumber(byte, 16))
	end))
end

T.Test("lzma decodes lzma alone and Source lump streams", function()
	for _, vector in ipairs(vectors) do
		local raw = from_hex(vector.raw)
		local compressed = from_hex(vector.compressed)
		T(lzma.Decode(compressed) == raw)["=="](true)
		local buffer = lzma.DecodeBuffer(import("goluwa/structs/buffer.lua").New(compressed, #compressed))
		T(buffer:GetSize())["=="](#raw)
	end
end)

T.Test("lzma worker result equals the inline result", function()
	local thread_pool = import("goluwa/thread_pool.lua")

	for _, vector in ipairs(vectors) do
		local raw = from_hex(vector.raw)
		local meta, blob = thread_pool.Run(lzma.thread_job, from_hex(vector.compressed), 1e9):Await()
		T(meta.size)["=="](#raw)
		T(ffi.string(blob.ptr, blob.len) == raw)["=="](true)
	end
end)

T.Test("lzma rejects corrupt and unsupported input without crashing", function()
	local compressed = from_hex(vectors[1].compressed)
	local corrupt = compressed:sub(1, 300) .. string.rep("\255", 40) .. compressed:sub(341)
	pcall(lzma.Decode, corrupt)
	pcall(lzma.Decode, compressed:sub(1, 200))
	T(pcall(lzma.Decode, "\xFD7zXZ\0xxxxxxxxxxxxxxxxxxxx"))["=="](false)
	local unknown = "\93\0\0\1\0" .. string.rep("\255", 8) .. compressed:sub(14)
	T(pcall(lzma.Decode, unknown))["=="](false)
end)
